import { Stump, prepare, discreteSearch, multiclassSearch } from './stumps.ts';
import type { BinaryRow, MultiRow } from './dataset.ts';
export type Stop = 'completed' | 'weak' | 'perfect' | 'converged';
interface WeightedRound {
  stump: Stump;
  weights: number[];
}
export interface DiscreteRound extends WeightedRound {
  kind: 'discrete';
  polarity: number;
  error: number;
  alpha: number;
  z: number;
  bound: number;
}
export interface RealRound extends WeightedRound {
  kind: 'real';
  z: number;
  bound: number;
}
export interface GentleRound extends WeightedRound {
  kind: 'gentle';
  error: number;
}
export interface LogitRound extends WeightedRound {
  kind: 'logit';
  error: number;
  loss: number;
}
export type Round = DiscreteRound | RealRound | GentleRound | LogitRound;
export interface Training {
  rounds: Round[];
  stop: Stop;
  cuts?: number[][];
}
export interface SammeRound {
  stump: Stump;
  error: number;
  alpha: number;
}
export function normalize(weights: number[]): number {
  let total = 0;
  for (const w of weights) total += w;
  for (let i = 0; i < weights.length; i++) weights[i] /= total;
  return total;
}
export function discrete(
  rows: BinaryRow[],
  maximumRounds: number,
  shrinkage = 1,
  initialWeights: number[] | null = null,
): Training {
  const plans = prepare(rows);
  const weights =
    initialWeights === null
      ? Array<number>(rows.length).fill(1 / rows.length)
      : initialWeights.slice();
  const rounds: DiscreteRound[] = [];
  let bound = 1;
  let stop: Stop = 'completed';
  for (let t = 0; t < maximumRounds; t++) {
    const candidate = discreteSearch(rows, weights, plans);
    const error = candidate.error;
    if (error >= 0.5) {
      stop = 'weak';
      break;
    }
    const alpha = error <= 1e-10 ? 1 : shrinkage * (0.5 * Math.log((1 - error) / error));
    const polarity = candidate.polarity;
    const stump = new Stump(
      candidate.feature,
      [candidate.threshold],
      [-polarity * alpha, polarity * alpha],
    );
    const before = weights.slice();
    rows.forEach((row, i) => {
      const decision = row.values[candidate.feature] > candidate.threshold ? polarity : -polarity;
      weights[i] *= decision === row.label ? Math.exp(-alpha) : Math.exp(alpha);
    });
    const z = normalize(weights);
    bound *= z;
    rounds.push({ kind: 'discrete', stump, polarity, error, alpha, z, bound, weights: before });
    if (error <= 1e-10) {
      stop = 'perfect';
      break;
    }
  }
  return { rounds, stop };
}
export function samme(
  rows: MultiRow[],
  classes: number,
  maximumRounds: number,
): { rounds: SammeRound[]; stop: Stop } {
  const plans = prepare(rows);
  const weights = Array<number>(rows.length).fill(1 / rows.length);
  const rounds: SammeRound[] = [];
  let stop: Stop = 'completed';
  for (let t = 0; t < maximumRounds; t++) {
    const { stump, error } = multiclassSearch(rows, weights, plans, classes);
    if (error >= (classes - 1) / classes) {
      stop = 'weak';
      break;
    }
    const alpha = error <= 1e-10 ? 1 : Math.log((1 - error) / error) + Math.log(classes - 1);
    rows.forEach((row, i) => {
      if (stump.output(row.values) !== row.category) weights[i] *= Math.exp(alpha);
    });
    normalize(weights);
    rounds.push({ stump, error, alpha });
    if (error <= 1e-10) {
      stop = 'perfect';
      break;
    }
  }
  return { rounds, stop };
}

import { readFileSync } from 'node:fs';
export interface ValuesRow {
  values: number[];
}
export interface BinaryRow extends ValuesRow {
  id: string;
  label: number;
}
export interface MultiRow extends ValuesRow {
  id: string;
  category: number;
}
export type Variant = 'discrete' | 'real' | 'gentle' | 'logit';
export interface Parameters {
  rounds: number;
  variants: Variant[];
  bins: number;
  smoothing: number;
  convergence: number;
  clip: number;
  folds: number;
  margins: number[];
  classes: number;
  sammeRounds: number;
  permutationRepeats: number;
  permutationSeed: number;
  noiseSeed: number;
  noise: number[];
  sizes: number[];
  shrinkage: number[];
  bootstrapSamples: number;
  bootstrapSeed: number;
}
const readLines = (name: string) =>
  readFileSync('input/' + name, 'ascii')
    .split('\n')
    .slice(0, -1);
function binaryRows(lines: string[]): BinaryRow[] {
  return lines.slice(1).map((line) => {
    const fields = line.split(',');
    return {
      id: fields[0],
      values: fields.slice(1, -1).map(Number),
      label: Number(fields[fields.length - 1]),
    };
  });
}
function variant(name: string): Variant {
  if (name === 'discrete' || name === 'real' || name === 'gentle' || name === 'logit') return name;
  throw new Error('Unknown variant');
}
export function readDataset() {
  const trainLines = readLines('train.csv');
  const testLines = readLines('test.csv');
  const multiLines = readLines('multiclass.csv');
  const multiTrain: MultiRow[] = [];
  const multiTest: MultiRow[] = [];
  for (const line of multiLines.slice(1)) {
    const fields = line.split(',');
    const row = {
      id: fields[0],
      values: fields.slice(1, -2).map(Number),
      category: Number(fields[fields.length - 2]),
    };
    (fields[fields.length - 1] === 'train' ? multiTrain : multiTest).push(row);
  }
  const s = readLines('params.txt').map((line) => line.split(' ').slice(1));
  const params: Parameters = {
    rounds: Number(s[0][0]),
    variants: s[1].map(variant),
    bins: Number(s[2][0]),
    smoothing: Number(s[3][0]),
    convergence: Number(s[4][0]),
    clip: Number(s[5][0]),
    folds: Number(s[6][0]),
    margins: s[7].map(Number),
    classes: Number(s[8][0]),
    sammeRounds: Number(s[9][0]),
    permutationRepeats: Number(s[10][0]),
    permutationSeed: Number(s[10][1]),
    noiseSeed: Number(s[11][0]),
    noise: s[11].slice(1).map(Number),
    sizes: s[12].map(Number),
    shrinkage: s[13].map(Number),
    bootstrapSamples: Number(s[14][0]),
    bootstrapSeed: Number(s[14][1]),
  };
  return {
    features: trainLines[0].split(',').slice(1, -1),
    train: binaryRows(trainLines),
    test: binaryRows(testLines),
    multiFeatures: multiLines[0].split(',').slice(1, -2),
    multiTrain,
    multiTest,
    params,
  };
}

import { mkdirSync, writeFileSync } from 'node:fs';
import type { BinaryRow, MultiRow } from './dataset.ts';
export function fixed(value: number | null, digits = 4): string {
  if (value === null) return '-';
  const magnitude = Math.abs(value);
  const text =
    magnitude >= 1e21 ? BigInt(magnitude) + '.' + '0'.repeat(digits) : magnitude.toFixed(digits);
  return value < 0 && Number(text) !== 0 ? '-' + text : text;
}
export const ratio = (a: number, b: number): string => (b > 0 ? fixed(a / b) : '-');
export const prediction = (score: number): number => (score > 0 ? 1 : -1);
export function auc(rows: BinaryRow[], scores: number[]): string {
  let positive = 0;
  let negative = 0;
  let wins = 0;
  let ties = 0;
  for (const row of rows) {
    if (row.label === 1) positive++;
    else negative++;
  }
  for (let a = 0; a < rows.length; a++) {
    if (rows[a].label === 1) {
      for (let b = 0; b < rows.length; b++) {
        if (rows[b].label === -1) {
          if (scores[a] > scores[b]) wins++;
          else if (scores[a] === scores[b]) ties++;
        }
      }
    }
  }
  return ratio(2 * wins + ties, 2 * positive * negative);
}
export function confusion(rows: MultiRow[], predictions: number[], classes: number): number[][] {
  const matrix = Array.from({ length: classes }, () => Array<number>(classes).fill(0));
  rows.forEach((row, i) => {
    matrix[row.category - 1][predictions[i] - 1]++;
  });
  return matrix;
}
export const countAtMost = (values: number[], threshold: number): number =>
  values.filter((v) => v <= threshold).length;
export function writeLines(name: string, lines: string[]): void {
  mkdirSync('output', { recursive: true });
  writeFileSync('output/' + name, lines.length ? lines.join('\n') + '\n' : '', 'ascii');
}

import { readDataset } from './dataset.ts';
import type { BinaryRow, MultiRow, ValuesRow, Parameters, Variant } from './dataset.ts';
import { discrete, samme } from './adaboost.ts';
import type { Training, Round } from './adaboost.ts';
import { real, gentle, logit } from './variants.ts';
import { largestIndex } from './stumps.ts';
import type { Stump } from './stumps.ts';
import { fixed, ratio, prediction, auc, confusion, countAtMost, writeLines } from './evaluation.ts';

type Data = ReturnType<typeof readDataset>;
type CV = ReturnType<typeof crossValidation>;
type Model = ReturnType<typeof analyzeModels>[number];
type Multi = ReturnType<typeof multiclassAnalysis>;
interface StumpRound {
  stump: Stump;
}
class Minstd {
  constructor(private state: number) {}
  next(): number {
    this.state = (48271 * this.state) % 2147483647;
    return this.state;
  }
}
function sum(values: number[]): number {
  let total = 0;
  for (const value of values) total += value;
  return total;
}
function trainVariant(name: Variant, rows: BinaryRow[], params: Parameters): Training {
  switch (name) {
    case 'discrete':
      return discrete(rows, params.rounds);
    case 'real':
      return real(rows, params);
    case 'gentle':
      return gentle(rows, params);
    case 'logit':
      return logit(rows, params);
  }
}
function score(rounds: StumpRound[], values: number[]): number {
  let result = 0;
  for (const round of rounds) result += round.stump.output(values);
  return result;
}
const scoreRows = (rounds: StumpRound[], rows: ValuesRow[]) =>
  rows.map((row) => score(rounds, row.values));
const magnitude = (round: StumpRound) => Math.max(...round.stump.values.map(Math.abs));
function errorCount(rows: BinaryRow[], scores: number[]): number {
  let errors = 0;
  rows.forEach((row, i) => {
    if (prediction(scores[i]) !== row.label) errors++;
  });
  return errors;
}
function loss(rows: BinaryRow[], scores: number[], variant: string): number {
  let total = 0;
  rows.forEach((row, i) => {
    total +=
      variant === 'logit'
        ? Math.log(1 + Math.exp(-2 * row.label * scores[i]))
        : Math.exp(-row.label * scores[i]);
  });
  return total / rows.length;
}
function minimumPosition(values: number[]): number {
  let best = 0;
  for (let i = 1; i < values.length; i++) if (values[i] < values[best]) best = i;
  return best;
}
function curve(rounds: Round[], train: BinaryRow[], test: BinaryRow[], variant: Variant) {
  const trainScores = train.map(() => 0);
  const testScores = test.map(() => 0);
  let scale = 0;
  return rounds.map((round) => {
    train.forEach((row, i) => {
      trainScores[i] += round.stump.output(row.values);
    });
    test.forEach((row, i) => {
      testScores[i] += round.stump.output(row.values);
    });
    scale += magnitude(round);
    return {
      trainErrors: errorCount(train, trainScores),
      testErrors: errorCount(test, testScores),
      trainLoss: loss(train, trainScores, variant),
      testLoss: loss(test, testScores, variant),
      minimum: Math.min(...train.map((row, i) => row.label * trainScores[i])) / scale,
    };
  });
}
function crossValidation(rows: BinaryRow[], params: Parameters) {
  const folds = Array.from({ length: params.folds }, (_, fold) => {
    const validation = rows.map((_, i) => i).filter((i) => i % params.folds === fold);
    const count = rows.length - validation.length;
    const model = discrete(
      rows,
      params.rounds,
      1,
      rows.map((_, i) => (i % params.folds === fold ? 0 : 1 / count)),
    );
    const scores = validation.map(() => 0);
    const errors: number[] = [];
    for (let t = 0; t < params.rounds; t++) {
      if (t < model.rounds.length) {
        validation.forEach((row, i) => {
          scores[i] += model.rounds[t].stump.output(rows[row].values);
        });
      }
      errors.push(validation.filter((row, i) => prediction(scores[i]) !== rows[row].label).length);
    }
    return { model, validation, count, errors };
  });
  const errors = Array<number>(params.rounds).fill(0);
  for (const fold of folds) for (let t = 0; t < params.rounds; t++) errors[t] += fold.errors[t];
  const selected = minimumPosition(errors) + 1;
  const scores = rows.map(() => 0);
  for (const fold of folds) {
    for (const i of fold.validation) {
      scores[i] = score(fold.model.rounds.slice(0, selected), rows[i].values);
    }
  }
  return { folds, errors, selected, scores };
}
function importance<R extends StumpRound>(
  rounds: R[],
  featureCount: number,
  valueOf: (round: R) => number = magnitude,
) {
  const features = Array.from({ length: featureCount }, (_, feature) => ({
    feature,
    score: 0,
    count: 0,
    share: 0,
  }));
  for (const round of rounds) {
    const item = features[round.stump.feature];
    item.score += valueOf(round);
    item.count++;
  }
  const total = sum(features.map((item) => item.score));
  for (const item of features) item.share = item.score / total;
  return features.sort((a, b) => b.score - a.score || a.feature - b.feature);
}
function analyzeModels(data: Data, cv: CV) {
  return data.params.variants.map((name) => {
    const full = trainVariant(name, data.train, data.params);
    const rounds = name === 'discrete' ? full.rounds.slice(0, cv.selected) : full.rounds.slice();
    const scale = sum(rounds.map(magnitude));
    const trainScores = scoreRows(rounds, data.train);
    const testScores = scoreRows(rounds, data.test);
    return {
      name,
      full,
      rounds,
      scale,
      trainScores,
      testScores,
      trainMargins: data.train.map((r, i) => (r.label * trainScores[i]) / scale),
      testMargins: data.test.map((r, i) => (r.label * testScores[i]) / scale),
      trainPredictions: trainScores.map(prediction),
      testPredictions: testScores.map(prediction),
      curve: curve(full.rounds, data.train, data.test, name),
      importance: importance(rounds, data.features.length),
    };
  });
}
function ensembleLines(data: Data, models: Model[], cv: CV): string[] {
  const lines: string[] = [];
  for (const { name, full } of models) {
    if (lines.length) lines.push('');
    let heading = `variant ${name} rounds ${full.rounds.length} stop ${full.stop}`;
    if (name === 'real') {
      heading += ` bins ${data.params.bins} smoothing ${fixed(data.params.smoothing)} convergence ${fixed(data.params.convergence, 6)}`;
    }
    if (name === 'logit') heading += ` clip ${fixed(data.params.clip)}`;
    lines.push(heading);
    if (name === 'real') {
      data.features.forEach((feature, j) =>
        lines.push(`cuts ${feature} ${full.cuts![j].map((v) => fixed(v)).join(' ')}`),
      );
    }
    full.rounds.forEach((round, t) => {
      const stump = round.stump;
      const prefix = `round ${t + 1} feature ${data.features[stump.feature]}`;
      if (round.kind === 'discrete') {
        lines.push(
          `${prefix} threshold ${fixed(stump.thresholds[0])} polarity ${round.polarity} error ${fixed(round.error)} alpha ${fixed(round.alpha)} z ${fixed(round.z)} bound ${fixed(round.bound)}`,
        );
        let maximum = 0;
        let squares = 0;
        round.weights.forEach((w, i) => {
          if (w > round.weights[maximum]) maximum = i;
          squares += w * w;
        });
        lines.push(
          `weights ${t + 1} max ${fixed(round.weights[maximum], 6)} id ${data.train[maximum].id} ess ${fixed(1 / squares)}`,
        );
      } else if (round.kind === 'real') {
        lines.push(
          `${prefix} z ${fixed(round.z)} bound ${fixed(round.bound)} values ${stump.values.map((v) => fixed(v)).join(' ')}`,
        );
      } else {
        lines.push(
          `${prefix} threshold ${fixed(stump.thresholds[0])} left ${fixed(stump.values[0])} right ${fixed(stump.values[1])} error ${fixed(round.error)}` +
            (round.kind === 'logit' ? ` loss ${fixed(round.loss)}` : ''),
        );
      }
    });
    if (name === 'discrete') {
      lines.push(
        `cv folds ${data.params.folds} selected ${cv.selected} errors ${cv.errors[cv.selected - 1]}/${data.train.length}`,
      );
      cv.folds.forEach((f, i) =>
        lines.push(
          `fold ${i + 1} train ${f.count} validation ${f.validation.length} rounds ${f.model.rounds.length} stop ${f.model.stop} selected ${f.errors[cv.selected - 1]}/${f.validation.length} final ${f.errors[f.errors.length - 1]}/${f.validation.length}`,
        ),
      );
      lines.push('cv_errors ' + cv.errors.join(' '));
    }
  }
  return lines;
}
function errorCurveLines(data: Data, models: Model[], multi: Multi): string[] {
  return [
    'variant,round,train_error,test_error,train_loss,test_loss,min_margin',
    ...models.flatMap((m) =>
      m.curve.map((r, i) =>
        [
          m.name,
          i + 1,
          ratio(r.trainErrors, data.train.length),
          ratio(r.testErrors, data.test.length),
          fixed(r.trainLoss),
          fixed(r.testLoss),
          fixed(r.minimum),
        ].join(','),
      ),
    ),
    ...multi.curve.map((r, i) =>
      [
        'samme',
        i + 1,
        ratio(r.train, data.multiTrain.length),
        ratio(r.test, data.multiTest.length),
        '-',
        '-',
        '-',
      ].join(','),
    ),
  ];
}
function predictionLines(data: Data, models: Model[]): string[] {
  const lines = ['id,variant,score,label,' + data.features.join(',')];
  data.test.forEach((row, i) => {
    for (const m of models) {
      const contributions = data.features.map(() => 0);
      for (const r of m.rounds) contributions[r.stump.feature] += r.stump.output(row.values);
      lines.push(
        [
          row.id,
          m.name,
          fixed(m.testScores[i]),
          m.testPredictions[i],
          ...contributions.map((v) => fixed(v)),
        ].join(','),
      );
    }
  });
  return lines;
}
function rocLines(data: Data, models: Model[]): string[] {
  const lines = ['variant,threshold,tp,fp'];
  for (const m of models) {
    for (const threshold of [...new Set(m.testScores)].sort((a, b) => b - a)) {
      let tp = 0;
      let fp = 0;
      data.test.forEach((r, i) => {
        if (m.testScores[i] >= threshold) {
          if (r.label === 1) tp++;
          else fp++;
        }
      });
      lines.push([m.name, fixed(threshold), tp, fp].join(','));
    }
  }
  return lines;
}
function importanceLines(items: ReturnType<typeof importance>, names: string[]): string[] {
  return items.map(
    (item, i) =>
      `${i + 1} ${names[item.feature]} score ${fixed(item.score)} share ${fixed(item.share)} rounds ${item.count}`,
  );
}
function permutationImportance(
  model: Model,
  rows: BinaryRow[],
  featureCount: number,
  repeats: number,
  generator: Minstd,
) {
  const base = rows.length - errorCount(rows, model.testScores);
  const results: { feature: number; drop: number; minimum: number; maximum: number }[] = [];
  for (let feature = 0; feature < featureCount; feature++) {
    const counts: number[] = [];
    let drop = 0;
    for (let r = 0; r < repeats; r++) {
      const permutation = rows.map((_, i) => i);
      for (let i = rows.length - 1; i >= 1; i--) {
        const other = generator.next() % (i + 1);
        [permutation[i], permutation[other]] = [permutation[other], permutation[i]];
      }
      let correct = 0;
      rows.forEach((row, i) => {
        const values = row.values.slice();
        values[feature] = rows[permutation[i]].values[feature];
        if (prediction(score(model.rounds, values)) === row.label) correct++;
      });
      counts.push(correct);
      drop += base - correct;
    }
    results.push({ feature, drop, minimum: Math.min(...counts), maximum: Math.max(...counts) });
  }
  return { base, results: results.sort((a, b) => b.drop - a.drop || a.feature - b.feature) };
}
function marginLines(data: Data, models: Model[]): string[] {
  const lines: string[] = [];
  const generator = new Minstd(data.params.permutationSeed);
  for (const m of models) {
    if (lines.length) lines.push('');
    lines.push(
      `variant ${m.name} rounds ${m.rounds.length} scale ${fixed(m.scale)}`,
      `train min ${fixed(Math.min(...m.trainMargins))} mean ${fixed(sum(m.trainMargins) / data.train.length)}`,
    );
    for (const threshold of data.params.margins) {
      const count = countAtMost(m.trainMargins, threshold);
      lines.push(
        `train le ${fixed(threshold)} ${count}/${data.train.length} ${ratio(count, data.train.length)}`,
      );
    }
    const histogram = Array<number>(20).fill(0);
    for (const margin of m.trainMargins) histogram[Math.min(19, Math.floor((margin + 1) * 10))]++;
    lines.push('histogram ' + histogram.join(' '));
    const hardest = data.train
      .map((_, i) => i)
      .sort((a, b) => m.trainMargins[a] - m.trainMargins[b] || a - b);
    for (const i of hardest.slice(0, 5)) {
      lines.push(
        `hardest ${data.train[i].id} label ${data.train[i].label} margin ${fixed(m.trainMargins[i])}`,
      );
    }
    lines.push(
      `test min ${fixed(Math.min(...m.testMargins))} mean ${fixed(sum(m.testMargins) / data.test.length)}`,
    );
    for (const threshold of data.params.margins) {
      const count = countAtMost(m.testMargins, threshold);
      lines.push(
        `test le ${fixed(threshold)} ${count}/${data.test.length} ${ratio(count, data.test.length)}`,
      );
    }
    for (const threshold of data.params.margins) {
      let count = 0;
      let correct = 0;
      data.test.forEach((row, i) => {
        if (Math.abs(m.testMargins[i]) > threshold) {
          count++;
          if (m.testPredictions[i] === row.label) correct++;
        }
      });
      lines.push(
        `test confident ${fixed(threshold)} ${count}/${data.test.length} correct ${correct}/${count} ${ratio(correct, count)}`,
      );
    }
    lines.push('importance', ...importanceLines(m.importance, data.features));
    const permutation = permutationImportance(
      m,
      data.test,
      data.features.length,
      data.params.permutationRepeats,
      generator,
    );
    lines.push(
      `permutation repeats ${data.params.permutationRepeats} base ${permutation.base}/${data.test.length}`,
    );
    permutation.results.forEach((r, i) =>
      lines.push(
        `${i + 1} ${data.features[r.feature]} drop ${ratio(r.drop, data.params.permutationRepeats * data.test.length)} min ${r.minimum}/${data.test.length} max ${r.maximum}/${data.test.length}`,
      ),
    );
  }
  return lines;
}
function shapeLines(data: Data, models: Model[]): string[] {
  const lines: string[] = [];
  for (const model of models) {
    if (lines.length) lines.push('');
    lines.push(`variant ${model.name} rounds ${model.rounds.length}`);
    data.features.forEach((name, feature) => {
      const rounds = model.rounds.filter((r) => r.stump.feature === feature);
      const thresholds = [...new Set(rounds.flatMap((r) => r.stump.thresholds))].sort(
        (a, b) => a - b,
      );
      const values = Array.from({ length: thresholds.length + 1 }, (_, interval) => {
