  const generator = new Minstd(seed);
  const counts = models.map((): number[] => []);
  for (let s = 0; s < samples; s++) {
    const selected = data.test.map(() => generator.next() % data.test.length);
    models.forEach((m, v) =>
      counts[v].push(selected.filter((i) => m.testPredictions[i] === data.test[i].label).length),
    );
  }
  const lines = [`bootstrap samples ${samples} seed ${seed}`];
  const tail = Math.floor(samples / 40);
  models.forEach((m, v) => {
    const sorted = counts[v].slice().sort((a, b) => a - b);
    lines.push(
      `${m.name} mean ${ratio(sum(counts[v]), samples * data.test.length)} low ${ratio(sorted[tail], data.test.length)} high ${ratio(sorted[samples - tail - 1], data.test.length)}`,
    );
  });
  for (const [a, b] of variantPairs(models)) {
    let first = 0;
    let tie = 0;
    let second = 0;
    for (let i = 0; i < samples; i++) {
      if (counts[a][i] > counts[b][i]) first++;
      else if (counts[a][i] < counts[b][i]) second++;
      else tie++;
