  for (const model of models) {
    const bins = Array.from({ length: 5 }, () => ({ count: 0, probability: 0, positive: 0 }));
    let brier = 0;
    data.test.forEach((row, i) => {
      const p = 1 / (1 + Math.exp(-2 * model.testScores[i]));
      const target = row.label === 1 ? 1 : 0;
      brier += (p - target) * (p - target);
      const bin = bins[Math.min(4, Math.floor(p * 5))];
      bin.count++;
      bin.probability += p;
      bin.positive += target;
    });
    lines.push(`calibration ${model.name} brier ${fixed(brier / data.test.length)}`);
    bins.forEach((bin, i) =>
