}
function summaryLines(data: Data, models: Model[], cv: CV): string[] {
  const lines = [
    `data train ${data.train.length} test ${data.test.length} features ${data.features.length} positives ${data.train.filter((r) => r.label === 1).length} ${data.test.filter((r) => r.label === 1).length}`,
  ];
  data.features.forEach((name, j) =>
    lines.push(
      `feature ${name} train ${featureSummary(data.train, j)} test ${featureSummary(data.test, j)}`,
    ),
  );
  lines.push(
    `cv selected ${cv.selected} errors ${cv.errors[cv.selected - 1]}/${data.train.length} rate ${ratio(cv.errors[cv.selected - 1], data.train.length)}`,
    metricsLine('oof', 'discrete', cv.selected, data.train, cv.scores),
  );
  for (const m of models) {
    lines.push(
      metricsLine('train', m.name, m.rounds.length, data.train, m.trainScores),
      metricsLine('test', m.name, m.rounds.length, data.test, m.testScores),
    );
  }
