    let agree = 0;
    let first = 0;
    let second = 0;
    data.test.forEach((row, i) => {
      const left = models[a].testPredictions[i];
      const right = models[b].testPredictions[i];
      if (left === right) agree++;
      if (left === row.label && right !== row.label) first++;
      if (right === row.label && left !== row.label) second++;
