    test.forEach((r, i) => {
      testScores[i][round.stump.output(r.values) - 1] += round.alpha;
    });
    return {
      train: multiclassErrors(train, trainScores.map(classPrediction)),
      test: multiclassErrors(test, testScores.map(classPrediction)),
    };
  });
