    model,
    curve: progress,
    trainScores,
    testScores,
    ovr,
    trainPredictions: trainScores.map(classPrediction),
    testPredictions: testScores.map(classPrediction),
    ovrTrain: train.map((_, i) => classPrediction(ovr.map((m) => m.trainScores[i]))),
