      );
    }
  }
  for (const shrinkage of params.shrinkage) {
    const m = discrete(train, params.rounds, shrinkage);
    const stats = experimentStats(m, train, test);
    lines.push(
      `shrinkage ${fixed(shrinkage)} ${experimentFields(m, stats, train.length, test.length)} test_min ${stats.minimum}/${test.length} at ${stats.at}`,
    );
  }
  const ranks = models.find((m) => m.name === 'discrete')!.importance;
  for (let count = 1; count <= data.features.length; count++) {
    const features = ranks
      .slice(0, count)
      .map((r) => r.feature)
      .sort((a, b) => a - b);
    const project = (rows: BinaryRow[]) =>
      rows.map((row) => ({ ...row, values: features.map((f) => row.values[f]) }));
    const reducedTrain = project(train);
    const reducedTest = project(test);
    const m = discrete(reducedTrain, cv.selected);
    const stats = experimentStats(m, reducedTrain, reducedTest);
    lines.push(
      `top ${count} features ${features.map((f) => data.features[f]).join(' ')} rounds ${m.rounds.length} train_errors ${stats.trainErrors}/${train.length} test_errors ${stats.testErrors}/${test.length}`,
    );
  }
  for (const q of params.noise) {
    const count = Math.floor((train.length * q) / 100);
    const generator = new Minstd(params.noiseSeed);
    const permutation = train.map((_, i) => i);
    for (let i = 0; i < count; i++) {
      const other = i + (generator.next() % (train.length - i));
      [permutation[i], permutation[other]] = [permutation[other], permutation[i]];
    }
    const flipped = new Set(permutation.slice(0, count));
    const noisy = train.map((row, i) => ({
      ...row,
      label: flipped.has(i) ? -row.label : row.label,
    }));
    lines.push(`noise ${q} flipped ${count}`);
    for (const variant of params.variants) {
      const m = trainVariant(variant, noisy, params);
      const stats = experimentStats(m, noisy, test);
      const weights = m.rounds[m.rounds.length - 1].weights;
      let flippedWeight = 0;
      for (let i = 0; i < train.length; i++) if (flipped.has(i)) flippedWeight += weights[i];
      lines.push(
        `${variant} ${experimentFields(m, stats, train.length, test.length)} test_min ${stats.minimum}/${test.length} at ${stats.at} flipped_weight ${fixed(flippedWeight)}`,
      );
    }
  }
  return lines;
}
